from __future__ import annotations

import copy
import hashlib
import hmac
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data


ALLOWED_ASSET_TYPES = {"component", "flow"}
DESIGN_INVOCATION_SCHEMA_VERSION = "agent-design-invocation/v1"
DESIGN_INVOCATION_KEYS = {
    "ok",
    "status",
    "schema_version",
    "artifact_refs",
    "tenant_id",
    "work_definition_id",
    "work_definition_revision",
    "approved_hash",
    "owner_id",
    "session_id",
    "catalog_snapshot_id",
    "work_definition",
    "acl_context",
    "skill_registry",
    "design_prompt",
    "trust_boundary",
    "trace_id",
}
SECRET_VALUE_PATTERNS = (
    re.compile(r"(?i)\b(?:api[_-]?key|password|passwd|secret|access[_-]?token|client[_-]?secret|authorization|cookie|session)\s*[:=]\s*[\"']?[^\s,;]{8,}"),
    re.compile(r"(?i)\b(?:bearer|basic)\s+\S{8,}"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\b[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"[a-zA-Z][a-zA-Z0-9+.-]*://[^/@\s]+:[^/@\s]+@"),
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
)
SECRET_KEY_TOKENS = {
    "apikey", "authorization", "clientsecret", "cookie", "credential", "password", "passwd",
    "privatekey", "pwd", "session", "smsession", "secret", "token",
}
ALLOWED_QUERY_KINDS = {"purpose", "capability", "exact", "risk", "reporting"}
WORK_DEFINITION_SCHEMA_VERSION = "work-definition/v1"
IDENTITY_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")
SEMANTIC_FIELDS = (
    "goal",
    "trigger",
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "decisions",
    "exceptions",
    "frequency_volume",
    "sla",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "automation_intent",
    "assumptions",
    "unresolved",
    "as_is_graph",
)
UNORDERED_LIST_KEYS = {
    "scope_in", "scope_out", "actors", "systems", "inputs", "outputs", "pains", "risks_controls",
    "constraints", "success_criteria", "assumptions", "unresolved", "nodes", "edges", "evidence_turn_ids",
    "conflicting_values",
}
NON_SEMANTIC_KEYS = {
    "x", "y", "position", "position_absolute", "style", "selected", "expanded", "display_order",
    "created_at", "updated_at", "submitted_at", "expires_at", "trace_id", "run_id", "job_id",
    "last_updated_revision", "confidence", "evidence_turn_ids", "processed_answer_batches",
}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _text_field(value: Any) -> tuple[str, str]:
    if isinstance(value, str):
        return value.strip(), "unknown"
    if isinstance(value, dict):
        return str(value.get("value") or value.get("text") or "").strip(), str(value.get("status") or "unknown")
    return "", "unknown"


def _safe_text(value: Any, maximum: int = 2000) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()[:maximum]


def _is_identity(value: Any) -> bool:
    return type(value) is str and IDENTITY_PATTERN.fullmatch(value) is not None


def _secret_key(value: Any) -> bool:
    text = str(value or "").casefold()
    compact = re.sub(r"[^a-z0-9]", "", text)
    parts = {item for item in re.split(r"[^a-z0-9]+", text) if item}
    if ("token" in parts and parts & {"max", "limit", "budget", "count"}) or (
        "session" in parts and parts & {"timeout", "ttl"}
    ):
        return False
    if "token" in compact and any(marker in compact for marker in {"maxtoken", "tokenlimit", "tokenbudget", "tokencount"}):
        return False
    if "session" in compact and any(marker in compact for marker in {"sessiontimeout", "sessionttl"}):
        return False
    return compact in SECRET_KEY_TOKENS or bool(parts & {"token", "session", "pwd"}) or any(
        marker in compact for marker in SECRET_KEY_TOKENS
    )


def _secret_material_kind(value: Any) -> str | None:
    if isinstance(value, dict):
        for key, item in value.items():
            if any(pattern.search(str(key).strip()) for pattern in SECRET_VALUE_PATTERNS):
                return "object_key"
            if _secret_key(key):
                return "secret_field"
            found = _secret_material_kind(item)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = _secret_material_kind(item)
            if found:
                return found
    elif isinstance(value, str) and value != "[REDACTED]" and any(
        pattern.search(value.strip()) for pattern in SECRET_VALUE_PATTERNS
    ):
        return "string_value"
    return None


def _canonical_hash(value: Any) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


def _canonicalize(value: Any, parent_key: str = "") -> Any:
    if isinstance(value, dict):
        return {
            key: _canonicalize(value[key], key)
            for key in sorted(value)
            if key not in NON_SEMANTIC_KEYS and not key.startswith("ui_") and not key.startswith("render_")
        }
    if isinstance(value, list):
        items = [_canonicalize(item, parent_key) for item in value]
        if parent_key in UNORDERED_LIST_KEYS:
            items.sort(key=lambda item: json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str))
        return items
    if isinstance(value, float):
        return float(format(value, ".15g"))
    return value


def _approved_work_projection(work: dict[str, Any]) -> tuple[dict[str, Any], str]:
    semantic = {field: copy.deepcopy(work.get(field)) for field in SEMANTIC_FIELDS}
    canonical_semantic = _canonicalize(semantic)
    canonical_text = json.dumps(
        canonical_semantic,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    actual_hash = "sha256:" + hashlib.sha256(canonical_text.encode("utf-8")).hexdigest()
    projection = {
        "schema_version": str(work.get("schema_version") or "work-definition/v1"),
        "work_definition_id": str(work.get("work_definition_id") or ""),
        "tenant_id": str(work.get("tenant_id") or ""),
        "owner_id": str(work.get("owner_id") or ""),
        "session_id": str(work.get("session_id") or ""),
        "channel_mode": str(work.get("channel_mode") or ""),
        "revision": work.get("revision"),
        "status": "APPROVED",
        "approved_hash": actual_hash,
        "preview_hash": actual_hash,
        **canonical_semantic,
    }
    return projection, actual_hash


def _confirmed_terms(value: Any, maximum: int = 30) -> list[str]:
    source = value if isinstance(value, list) else []
    result: list[str] = []
    for item in source[:maximum]:
        if isinstance(item, dict):
            provenance = item.get("provenance") if isinstance(item.get("provenance"), dict) else {}
            status = str(item.get("status") or item.get("provenance_status") or provenance.get("status") or "unknown").lower()
            if status not in {"confirmed", "approved"}:
                continue
            text = _safe_text(item.get("name") or item.get("title") or item.get("value"), 200)
        else:
            continue
        if text and text not in result:
            result.append(text)
    return result


def build_design_scope(
    work_definition: Any,
    *,
    tenant_id: str,
    catalog_snapshot_id: str,
    acl_context: Any,
    design_prompt: str = "",
) -> dict[str, Any]:
    """Validate and seal every approved design input into one typed scope.

    F20 exposes these values only on this component. Downstream components
    receive this immutable identity tuple instead of independent node tweaks.
    """
    trace_id = str(uuid.uuid4())
    work = _payload(work_definition)
    acl = _payload(acl_context)
    tenant = _safe_text(tenant_id, 200)
    snapshot = _safe_text(catalog_snapshot_id, 200)
    bounded_design_prompt = _safe_text(design_prompt, 4000)
    if not _is_identity(tenant_id):
        return _error(trace_id, "TENANT_REQUIRED", "tenant_id가 필요합니다.")
    if not _is_identity(catalog_snapshot_id):
        return _error(trace_id, "CATALOG_SNAPSHOT_ID_INVALID", "활성 catalog snapshot ID 형식이 유효하지 않습니다.")
    if set(acl) - {"subject_id", "groups"}:
        return _error(trace_id, "ACL_CONTEXT_FIELDS_INVALID", "ACL context에 허용되지 않은 필드가 있습니다.")
    raw_groups = acl.get("groups", [])
    if (
        not _is_identity(acl.get("subject_id"))
        or not isinstance(raw_groups, list)
        or len(raw_groups) > 100
        or any(not _is_identity(item) for item in raw_groups)
    ):
        return _error(trace_id, "ACL_CONTEXT_IDENTITY_INVALID", "ACL subject와 group identity 형식이 유효하지 않습니다.")
    if _secret_material_kind(acl):
        return _error(trace_id, "ACL_CONTEXT_SECRET_MATERIAL_DETECTED", "ACL context에 secret 원문을 넣을 수 없습니다.")
    canonical_acl = {
        "subject_id": str(acl["subject_id"]),
        "groups": sorted({str(item).lower() for item in raw_groups}),
    }
    if not work:
        return _error(trace_id, "INVALID_WORK_DEFINITION", "승인 업무 정의가 필요합니다.")
    if any(pattern.search(bounded_design_prompt) for pattern in SECRET_VALUE_PATTERNS):
        return _error(
            trace_id,
            "DESIGN_PROMPT_SECRET_MATERIAL_DETECTED",
            "추가 설계 프롬프트에는 secret 원문을 넣을 수 없습니다.",
        )
    if type(work.get("schema_version")) is not str or work.get("schema_version") != WORK_DEFINITION_SCHEMA_VERSION:
        return _error(
            trace_id,
            "WORK_DEFINITION_SCHEMA_INVALID",
            f"승인 업무 정의 schema_version은 {WORK_DEFINITION_SCHEMA_VERSION}이어야 합니다.",
        )
    for field in ("tenant_id", "owner_id", "session_id", "work_definition_id"):
        if not _is_identity(work.get(field)):
            return _error(
                trace_id,
                "WORK_DEFINITION_IDENTITY_INVALID",
                f"승인 업무 정의 {field}가 canonical identity 형식이 아닙니다.",
            )
    if work.get("channel_mode") != "native_hitl":
        return _error(trace_id, "WORK_DEFINITION_CHANNEL_INVALID", "승인 업무 정의 channel_mode가 유효하지 않습니다.")
    state = work.get("status")
    approved_hash = work.get("approved_hash")
    work_id = work.get("work_definition_id")
    raw_revision = work.get("revision")
    if type(raw_revision) is not int:
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 필요합니다.")
    work_revision = raw_revision
    if work_revision < 0:
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 필요합니다.")
    if state != "APPROVED" or type(approved_hash) is not str or not re.fullmatch(r"sha256:[0-9a-f]{64}", approved_hash):
        return _error(trace_id, "WORK_DEFINITION_NOT_APPROVED", "approved 상태와 유효한 approved_hash가 필요합니다.")
    if work.get("tenant_id") != tenant:
        return _error(trace_id, "WORK_DEFINITION_TENANT_MISMATCH", "승인 업무 정의 tenant가 설계 tenant와 다릅니다.")
    try:
        approved_work, actual_approved_hash = _approved_work_projection(work)
    except (TypeError, ValueError):
        return _error(trace_id, "WORK_DEFINITION_CANONICALIZATION_FAILED", "승인 업무 정의의 의미 필드를 canonicalize할 수 없습니다.")
    if not hmac.compare_digest(approved_hash.lower(), actual_approved_hash.lower()):
        return _error(trace_id, "WORK_DEFINITION_APPROVAL_HASH_MISMATCH", "승인 이후 업무 의미가 변경되었거나 승인 hash가 유효하지 않습니다.")
    semantic_secret_kind = _secret_material_kind(
        {field: approved_work.get(field) for field in SEMANTIC_FIELDS}
    )
    if semantic_secret_kind:
        return _error(
            trace_id,
            "WORK_DEFINITION_SECRET_MATERIAL_DETECTED",
            "승인 업무 정의의 의미 필드에 secret 원문이 포함되어 설계를 중단했습니다.",
        )
    scope_core = {
        "schema_version": "agent-design-scope/v1",
        "tenant_id": tenant,
        "catalog_snapshot_id": snapshot,
        "work_definition_id": work_id,
        "work_definition_revision": work_revision,
        "approved_hash": approved_hash,
        "work_definition": approved_work,
        "acl_context": canonical_acl,
        "design_prompt": bounded_design_prompt,
    }
    return {
        "ok": True,
        "status": "COMPLETED",
        **scope_core,
        "design_scope_sha256": _canonical_hash(scope_core),
        "trace_id": trace_id,
    }


def _step_items(value: Any, maximum: int = 100) -> list[dict[str, str]]:
    source = value if isinstance(value, list) else []
    result: list[dict[str, str]] = []
    for index, item in enumerate(source[:maximum], start=1):
        if not isinstance(item, dict):
            continue
        step_id = _safe_text(item.get("step_id") or item.get("id") or f"step-{index}", 100)
        title = _safe_text(item.get("title") or item.get("name"), 300)
        capability = _safe_text(item.get("capability") or item.get("description") or item.get("action"), 1000)
        if title or capability:
            result.append({"step_id": step_id, "title": title, "capability": capability})
    return result


def build_search_query_plan(
    work_definition: Any,
    *,
    tenant_id: str,
    catalog_snapshot_id: str,
    acl_context: Any,
    design_prompt: str = "",
    max_queries: int = 30,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    scope = build_design_scope(
        work_definition,
        tenant_id=tenant_id,
        catalog_snapshot_id=catalog_snapshot_id,
        acl_context=acl_context,
        design_prompt=design_prompt,
    )
    if not scope.get("ok"):
        return scope
    work = scope["work_definition"]
    acl = scope["acl_context"]
    tenant = scope["tenant_id"]
    snapshot = scope["catalog_snapshot_id"]
    approved_hash = scope["approved_hash"]

    max_queries = max(1, min(50, int(max_queries or 30)))
    goal, _ = _text_field(work.get("goal") or work.get("purpose"))
    title, _ = _text_field(work.get("title"))
    steps = _step_items(work.get("steps") or (work.get("as_is_graph") or {}).get("nodes"))
    systems = _confirmed_terms(work.get("systems"))
    inputs = _confirmed_terms(work.get("inputs"))
    outputs = _confirmed_terms(work.get("outputs"))
    risks = _confirmed_terms(work.get("risks_controls"))
    prompt = scope["design_prompt"]
    queries: list[dict[str, Any]] = []

    def add(kind: str, text: str, expected: list[str], purpose: str, step_ids: list[str] | None = None) -> None:
        clean = _safe_text(text, 2000)
        if not clean or kind not in ALLOWED_QUERY_KINDS or len(queries) >= max_queries:
            return
        identity = {"kind": kind, "text": clean, "expected": expected, "step_ids": step_ids or []}
        query_id = "q-" + hashlib.sha256(json.dumps(identity, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()[:16]
        if any(item["query_id"] == query_id for item in queries):
            return
        queries.append(
            {
                "query_id": query_id,
                "kind": kind,
                "text": clean,
                "purpose": _safe_text(purpose, 500),
                "expected_asset_types": [item for item in expected if item in ALLOWED_ASSET_TYPES],
                "matched_work_steps": step_ids or [],
                "required_filters": {
                    "tenant_id": tenant,
                    "snapshot_id": snapshot,
                    "acl_required": True,
                },
            }
        )

    add("purpose", " ".join(item for item in (title, goal, prompt) if item), ["component", "flow"], "전체 업무 목적과 유사한 자산 탐색")
    for step in steps:
        add(
            "capability",
            " ".join(item for item in (step["title"], step["capability"]) if item),
            ["component", "flow"],
            "업무 단계 capability 충족 자산 탐색",
            [step["step_id"]],
        )
    for system in systems:
        add("exact", system, ["component", "flow"], "사용자가 확인한 시스템/API/제품명 exact 또는 alias 탐색")
    for risk in risks:
        add("risk", risk, ["component", "flow"], "승인·보안·예외 처리 capability 탐색")
    if outputs:
        add("reporting", " ".join(outputs), ["component", "flow"], "업무 출력과 보고 capability 탐색")
    if not queries:
        return _error(trace_id, "NO_SEARCHABLE_REQUIREMENT", "검색 query를 만들 확인된 업무 정보가 없습니다.")

    plan_core = {
        "schema_version": "search-query-plan.v1",
        "tenant_id": tenant,
        "catalog_snapshot_id": snapshot,
        "work_definition_id": str(work.get("work_definition_id") or ""),
        "work_definition_revision": scope["work_definition_revision"],
        "approved_hash": approved_hash,
        "design_scope_sha256": scope["design_scope_sha256"],
        "acl": {
            "subject_id": str(acl.get("subject_id")),
            "groups": sorted(_confirmed_acl_groups(acl.get("groups"))),
        },
        "queries": queries,
        "confirmed_exact_terms": systems,
        "confirmed_inputs": inputs,
        "confirmed_outputs": outputs,
    }
    return {
        "ok": True,
        "status": "COMPLETED",
        **plan_core,
        "query_plan_sha256": _canonical_hash(plan_core),
        "trace_id": trace_id,
    }


def _confirmed_acl_groups(value: Any) -> set[str]:
    source = value if isinstance(value, list) else []
    return {str(item).strip().lower() for item in source[:100] if str(item).strip()}


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


def validate_design_invocation(value: Any) -> dict[str, Any]:
    """Validate the single trusted input exposed by F20 and Run Flow."""

    trace_id = str(uuid.uuid4())
    invocation = _payload(value)
    if invocation.get("ok") is not True or invocation.get("status") != "READY_FOR_DESIGN":
        return _error(trace_id, "DESIGN_INVOCATION_NOT_READY", "MongoDB 권위 데이터 재확인이 완료된 invocation이 필요합니다.")
    if invocation.get("schema_version") != DESIGN_INVOCATION_SCHEMA_VERSION:
        return _error(trace_id, "DESIGN_INVOCATION_SCHEMA_INVALID", "승인 설계 invocation schema가 유효하지 않습니다.")
    if set(invocation) - DESIGN_INVOCATION_KEYS:
        return _error(trace_id, "DESIGN_INVOCATION_FIELDS_INVALID", "승인 설계 invocation에 허용되지 않은 필드가 있습니다.")
    work = _payload(invocation.get("work_definition"))
    acl = _payload(invocation.get("acl_context"))
    registry_payload = invocation.get("skill_registry")
    if isinstance(registry_payload, dict):
        registry = registry_payload.get("skills")
    else:
        registry = registry_payload
    if not isinstance(registry, list) or len(registry) > 500 or any(not isinstance(item, dict) for item in registry):
        return _error(trace_id, "DESIGN_INVOCATION_SKILL_REGISTRY_INVALID", "승인 Skill registry 입력이 유효하지 않습니다.")
    tenant_id = invocation.get("tenant_id")
    snapshot_id = invocation.get("catalog_snapshot_id")
    design_prompt = invocation.get("design_prompt", "")
    if not _is_identity(tenant_id) or not _is_identity(snapshot_id):
        return _error(trace_id, "DESIGN_INVOCATION_IDENTITY_INVALID", "tenant 또는 active snapshot identity가 유효하지 않습니다.")
    if not isinstance(design_prompt, str) or len(design_prompt) > 20000:
        return _error(trace_id, "DESIGN_INVOCATION_PROMPT_INVALID", "추가 설계 프롬프트가 유효하지 않습니다.")
    if not work or work.get("tenant_id") != tenant_id:
        return _error(trace_id, "DESIGN_INVOCATION_WORK_MISMATCH", "승인 업무 정의와 invocation tenant가 일치하지 않습니다.")
    if not acl or acl.get("subject_id") != work.get("owner_id"):
        return _error(trace_id, "DESIGN_INVOCATION_ACL_MISMATCH", "인증 사용자와 승인 업무 소유자가 일치하지 않습니다.")
    authority = invocation.get("trust_boundary")
    if not isinstance(authority, dict) or authority.get("work_definition_source") != "mongodb-canonical-approved":
        return _error(trace_id, "DESIGN_INVOCATION_AUTHORITY_INVALID", "MongoDB 권위 데이터 재확인 증거가 필요합니다.")
    return {
        "ok": True,
        "status": "READY",
        "schema_version": DESIGN_INVOCATION_SCHEMA_VERSION,
        "tenant_id": str(tenant_id),
        "catalog_snapshot_id": str(snapshot_id),
        "work_definition": copy.deepcopy(work),
        "acl_context": copy.deepcopy(acl),
        "skill_registry": copy.deepcopy(registry),
        "design_prompt": design_prompt,
        "authority": copy.deepcopy(authority),
        "trace_id": trace_id,
    }


class SearchQueryPlannerComponent(Component):
    display_name = "20 Search Query Planner"
    description = "MongoDB 권위 데이터에서 만든 단일 invocation을 검증하고 검색 query plan으로 변환합니다."
    icon = "ListFilter"
    name = "SearchQueryPlanner"

    inputs = [
        DataInput(name="design_invocation", display_name="Approved Design Invocation", required=True),
        IntInput(name="max_queries", display_name="Maximum Queries", value=30, advanced=True),
    ]
    outputs = [
        Output(
            name="design_scope",
            display_name="Sealed Design Scope",
            method="build_scope",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="query_plan",
            display_name="Search Query Plan",
            method="build_query_plan",
            types=["Data"],
            group_outputs=True,
        ),
        Output(
            name="approved_skill_registry",
            display_name="Approved Skill Registry",
            method="build_skill_registry",
            types=["Data"],
            group_outputs=True,
        ),
    ]

    def _validated_invocation(self) -> dict[str, Any]:
        result = getattr(self, "_invocation_result", None)
        if not isinstance(result, dict):
            result = validate_design_invocation(getattr(self, "design_invocation", None))
            self._invocation_result = result
        return result

    def build_scope(self) -> Data:
        invocation = self._validated_invocation()
        result = invocation if invocation.get("ok") is not True else build_design_scope(
            invocation["work_definition"],
            tenant_id=invocation["tenant_id"],
            catalog_snapshot_id=invocation["catalog_snapshot_id"],
            acl_context=invocation["acl_context"],
            design_prompt=invocation["design_prompt"],
        )
        self.status = f"Design scope: {result.get('status')}"
        return Data(data=result)

    def build_query_plan(self) -> Data:
        invocation = self._validated_invocation()
        result = invocation if invocation.get("ok") is not True else build_search_query_plan(
            invocation["work_definition"],
            tenant_id=invocation["tenant_id"],
            catalog_snapshot_id=invocation["catalog_snapshot_id"],
            acl_context=invocation["acl_context"],
            design_prompt=invocation["design_prompt"],
            max_queries=getattr(self, "max_queries", 30),
        )
        self.status = f"Query plan: {result.get('status')} / queries={len(result.get('queries', []))}"
        return Data(data=result)

    def build_skill_registry(self) -> Data:
        invocation = self._validated_invocation()
        if invocation.get("ok") is not True:
            return Data(data=copy.deepcopy(invocation))
        return Data(
            data={
                "ok": True,
                "status": "COMPLETED",
                "tenant_id": invocation["tenant_id"],
                "skills": copy.deepcopy(invocation["skill_registry"]),
                "authority": copy.deepcopy(invocation["authority"]),
                "trace_id": invocation["trace_id"],
            }
        )

from __future__ import annotations

"""Create locked query vectors through the connected Langflow Embedding Model."""

import hashlib
import hmac
import json
import math
import re
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, HandleInput, IntInput, Output
from lfx.schema import Data


_RUNTIME_CONTRACT_SCHEMA = "embedding-runtime-contract/v2"
_MAX_EMBEDDING_DIMENSION = 65536
_RUNTIME_CLASS_PATTERN = re.compile(
    r"^<class '([A-Za-z_][A-Za-z0-9_]*(?:\.(?:[A-Za-z_][A-Za-z0-9_]*|<locals>))*)'>$"
)


def _payload(value: Any, field: str) -> dict[str, Any]:
    data = getattr(value, "data", None)
    value = data if isinstance(data, dict) else value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(f"{field} must be JSON") from exc
    if not isinstance(value, dict):
        raise ValueError(f"{field} must be an object")
    if field == "query_plan" and isinstance(value.get("query_plan"), dict):
        value = value["query_plan"]
    return value


def _canonical_hash(value: Any) -> str:
    material = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def _verified_plan_locks(plan: dict[str, Any]) -> dict[str, str]:
    lock_fields = ("design_scope_sha256", "query_plan_sha256")
    locks = {field: str(plan.get(field) or "") for field in lock_fields}
    if any(not re.fullmatch(r"sha256:[0-9a-fA-F]{64}", value) for value in locks.values()):
        raise ValueError("query plan scope/hash lock is missing or invalid")
    plan_core = {
        key: value
        for key, value in plan.items()
        if key not in {"ok", "status", "query_plan_sha256", "trace_id"}
    }
    if not hmac.compare_digest(locks["query_plan_sha256"].lower(), _canonical_hash(plan_core).lower()):
        raise ValueError("query_plan_sha256 does not match query plan")
    return locks


def _queries(plan: dict[str, Any], maximum: int) -> list[dict[str, str]]:
    raw = plan.get("queries")
    if not isinstance(raw, list) or not raw:
        raise ValueError("query_plan.queries is required")
    if len(raw) > maximum:
        raise ValueError("query count exceeds max_queries")
    result: list[dict[str, str]] = []
    ids: set[str] = set()
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            raise ValueError("each query must be an object")
        query_id = str(item.get("query_id") or item.get("id") or f"query-{index + 1}").strip()[:200]
        text = str(item.get("text") or item.get("query") or "").strip()[:20_000]
        if not query_id or query_id in ids or not text:
            raise ValueError("query IDs must be unique and query text must be present")
        ids.add(query_id)
        result.append({"id": query_id, "text": text})
    return result


def _underlying_embedding(embedding: Any) -> Any:
    if embedding is None:
        raise ValueError("A connected Embedding Model is required")
    try:
        underlying = getattr(embedding, "embeddings", None)
    except Exception:  # noqa: BLE001 - provider wrappers can reject metadata reads
        underlying = None
    return embedding if underlying is None else underlying


def _model_id_text(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    text = value.strip()
    return text if 0 < len(text) <= 500 else ""


def _model_id(embedding: Any, underlying: Any) -> str:
    """Resolve only a provider-selected model identity; never infer from a class name."""
    try:
        available_models = getattr(embedding, "available_models", None)
    except Exception:  # noqa: BLE001 - provider wrappers can reject metadata reads
        available_models = None
    if isinstance(available_models, dict):
        matches = {
            text
            for candidate_id, candidate in available_models.items()
            if candidate is underlying and (text := _model_id_text(candidate_id))
        }
        if len(matches) > 1:
            raise ValueError("Embedding Model identity resolves to more than one configured model ID")
        if matches:
            return next(iter(matches))
    candidates: list[Any] = []
    try:
        candidates.append(getattr(underlying, "model_name", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "model", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "model_id", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "deployment_name", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    try:
        candidates.append(getattr(underlying, "deployment", None))
    except Exception:  # noqa: BLE001 - provider model metadata is heterogeneous
        pass
    for candidate in candidates:
        text = _model_id_text(candidate)
        if text:
            return text
    raise ValueError("The connected Embedding Model does not expose a stable model identity")


def _runtime_class(underlying: Any) -> str:
    rendered = str(type(underlying))
    match = _RUNTIME_CLASS_PATTERN.fullmatch(rendered) if len(rendered) <= 1024 else None
    value = match.group(1) if match else ""
    if not value or len(value) > 1000:
        raise ValueError("The connected Embedding Model does not expose a stable runtime class")
    return value


def _runtime_contract(embedding: Any, dimension: int) -> dict[str, Any]:
    if isinstance(dimension, bool) or not isinstance(dimension, int) or not 1 <= dimension <= _MAX_EMBEDDING_DIMENSION:
        raise ValueError("The embedding response dimension is invalid")
    underlying = _underlying_embedding(embedding)
    contract = {
        "schema_version": _RUNTIME_CONTRACT_SCHEMA,
        "runtime_class": _runtime_class(underlying),
        "model_id": _model_id(embedding, underlying),
        "dimension": dimension,
    }
    return {**contract, "fingerprint": _canonical_hash(contract)}


def _vectors(value: Any, expected_count: int, dimension: int | None, query_ids: list[str]) -> tuple[list[list[float]], int]:
    if not isinstance(value, list) or len(value) != expected_count:
        raise ValueError("The embedding response count does not match the query batch")
    actual_dimension = dimension
    result: list[list[float]] = []
    for index, vector in enumerate(value):
        query_id = query_ids[index]
        if not isinstance(vector, list) or not vector:
            raise ValueError(f"The embedding response vector is missing for query_id={query_id}")
        if actual_dimension is None:
            actual_dimension = len(vector)
            if not 1 <= actual_dimension <= _MAX_EMBEDDING_DIMENSION:
                raise ValueError("The embedding response dimension is invalid")
        if len(vector) != actual_dimension:
            raise ValueError(f"The embedding response vector dimension is invalid for query_id={query_id}")
        normalized: list[float] = []
        for item in vector:
            if isinstance(item, bool):
                raise ValueError(f"The embedding response contains a boolean for query_id={query_id}")
            try:
                number = float(item)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"The embedding response contains a non-numeric value for query_id={query_id}") from exc
            if not math.isfinite(number):
                raise ValueError(f"The embedding response contains a non-finite value for query_id={query_id}")
            normalized.append(number)
        result.append(normalized)
    if actual_dimension is None:
        raise ValueError("The embedding response did not contain a vector dimension")
    return result, actual_dimension


def _embed_documents(embedding: Any, texts: list[str], query_ids: list[str], dimension: int | None) -> tuple[list[list[float]], int]:
    try:
        method = getattr(embedding, "embed_documents", None)
    except Exception as exc:  # noqa: BLE001 - provider wrappers can expose arbitrary properties
        raise ValueError("The connected Embedding Model could not be used") from exc
    if not callable(method):
        raise ValueError("The connected Embedding Model does not provide embed_documents")
    try:
        raw_vectors = method(texts)
    except Exception as exc:  # noqa: BLE001 - providers expose heterogeneous error types
        raise RuntimeError("The connected Embedding Model failed to vectorize the query batch") from exc
    return _vectors(raw_vectors, len(texts), dimension, query_ids)


class SearchQueryEmbeddingBatcherComponent(Component):
    display_name = "29 Search Query Embedding Batcher"
    description = "Vectorize locked search queries through the connected Langflow Embedding Model in bounded batches."
    icon = "Binary"
    name = "SearchQueryEmbeddingBatcher"

    inputs = [
        DataInput(name="query_plan", display_name="Search Query Plan", required=True),
        HandleInput(name="embedding", display_name="Embedding Model", input_types=["Embeddings"], required=True),
        IntInput(name="batch_size", display_name="Embedding Batch Size", value=16, advanced=True),
        IntInput(name="max_queries", display_name="Maximum Queries", value=30, advanced=True),
    ]
    outputs = [Output(name="query_vectors", display_name="ID-preserving Query Vectors", method="build_query_vectors", types=["Data"])]

    def build_query_vectors(self) -> Data:
        plan = _payload(getattr(self, "query_plan", None), "query_plan")
        locks = _verified_plan_locks(plan)
        maximum = max(1, min(int(getattr(self, "max_queries", 30) or 30), 100))
        queries = _queries(plan, maximum)
        embedding = getattr(self, "embedding", None)
        underlying = _underlying_embedding(embedding)
        # Resolve model metadata before the first provider request so unknown model
        # identities fail closed without creating an untraceable vector snapshot.
        _model_id(embedding, underlying)
        _runtime_class(underlying)
        batch_size = max(1, min(int(getattr(self, "batch_size", 16) or 16), 128))
        vectors: dict[str, list[float]] = {}
        dimension: int | None = None
        for start in range(0, len(queries), batch_size):
            batch = queries[start : start + batch_size]
            batch_vectors, dimension = _embed_documents(
                embedding,
                [item["text"] for item in batch],
                [item["id"] for item in batch],
                dimension,
            )
            for item, vector in zip(batch, batch_vectors):
                vectors[item["id"]] = vector
        contract = _runtime_contract(embedding, dimension if dimension is not None else 0)
        result = {
            "ok": True,
            "status": "VECTORIZED",
            "schema_version": "query-vectors/v1",
            "vectors": vectors,
            "query_order": [item["id"] for item in queries],
            "embedding_contract": contract,
            **locks,
        }
        self.status = f"Vectorized {len(vectors)} queries with {contract['model_id']} ({contract['dimension']}d)."
        return Data(data=result)

from __future__ import annotations

import json
import hashlib
import hmac
import math
import re
import unicodedata
import uuid
from datetime import datetime
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput
from lfx.schema import Data
from pymongo import MongoClient
from pymongo.errors import ConfigurationError, ConnectionFailure, OperationFailure, PyMongoError, ServerSelectionTimeoutError


PROVIDER_MODES = {"native_rank_fusion", "native_score_fusion", "application_rrf"}
TECHNICAL_STATUSES = {"metadata_only", "ports_extracted", "flow_graph_extracted", "verified_runtime"}
MAX_QUERY_COUNT = 30
MAX_NATIVE_QUERY_COUNT = 12
MAX_SOURCE_CANDIDATES = 100
QUERY_KIND_WEIGHTS = {
    "purpose": 1.20,
    "capability": 1.25,
    "exact": 1.50,
    "risk": 1.15,
    "reporting": 1.00,
}
_RUNTIME_CONTRACT_SCHEMA = "embedding-runtime-contract/v2"
_RUNTIME_CONTRACT_FIELDS = ("schema_version", "runtime_class", "model_id", "dimension", "fingerprint")
_MAX_EMBEDDING_DIMENSION = 65536


def _safe_identifier(value: Any, default: str) -> str:
    text = str(value or default).strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", text):
        raise ValueError("INVALID_PROVIDER_IDENTIFIER")
    return text


def _payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list)):
        return data
    if isinstance(value, str) and value.strip():
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return {}
    return {}


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    if callable(getter):
        return str(getter())
    return str(value or "")


def _canonical_hash(value: Any) -> str:
    material = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def _string_list(value: Any, maximum: int = 100) -> list[str]:
    if isinstance(value, str):
        source = re.split(r"[,;\n]", value)
    elif isinstance(value, (list, tuple, set)):
        source = list(value)
    else:
        source = []
    result: list[str] = []
    for item in source[:maximum]:
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


def _normalize_exact_key(value: Any) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).casefold().strip()
    return re.sub(r"\s+", " ", text)[:500]


def _acl_filter(tenant_id: str, acl: dict[str, Any]) -> dict[str, Any]:
    groups = [item.lower() for item in _string_list(acl.get("groups"))]
    subject_id = str(acl.get("subject_id") or "")
    choices: list[dict[str, Any]] = [{"acl.visibility": "tenant"}]
    if groups:
        choices.append({"acl.visibility": "group", "acl.groups": {"$in": groups}})
    if subject_id:
        choices.append({"acl.visibility": "private", "acl.subjects": subject_id})
    return {"tenant_id": tenant_id, "$or": choices}


def _acl_allows(document: dict[str, Any], tenant_id: str, snapshot_id: str, acl: dict[str, Any]) -> bool:
    if str(document.get("tenant_id") or "") != tenant_id:
        return False
    if str(document.get("snapshot_id") or "") != snapshot_id:
        return False
    document_acl = document.get("acl") if isinstance(document.get("acl"), dict) else None
    if document_acl is None:
        return False
    visibility = str(document_acl.get("visibility") or "").lower()
    groups = {item.lower() for item in _string_list(acl.get("groups"))}
    allowed_groups = {item.lower() for item in _string_list(document_acl.get("groups"))}
    subjects = set(_string_list(document_acl.get("subjects")))
    subject_id = str(acl.get("subject_id") or "")
    if visibility == "tenant":
        return True
    if visibility == "group":
        return bool(groups & allowed_groups)
    return visibility == "private" and bool(subject_id) and subject_id in subjects


def _runtime_contract_text(value: Any, maximum: int = 500) -> str:
    if not isinstance(value, str):
        return ""
    text = value.strip()
    return text if 0 < len(text) <= maximum else ""


def _embedding_runtime_contract(value: Any) -> dict[str, Any]:
    """Validate the portable runtime identity emitted by the vectorization node."""
    if not isinstance(value, dict) or set(value) != set(_RUNTIME_CONTRACT_FIELDS):
        raise ValueError("EMBEDDING_RUNTIME_CONTRACT_INVALID")
    if value.get("schema_version") != _RUNTIME_CONTRACT_SCHEMA:
        raise ValueError("EMBEDDING_RUNTIME_CONTRACT_INVALID")
    runtime_class = _runtime_contract_text(value.get("runtime_class"), maximum=1000)
    model_id = _runtime_contract_text(value.get("model_id"))
    dimension = value.get("dimension")
    fingerprint = value.get("fingerprint")
    if (
        not runtime_class
        or not model_id
        or isinstance(dimension, bool)
        or not isinstance(dimension, int)
        or not 1 <= dimension <= _MAX_EMBEDDING_DIMENSION
        or not isinstance(fingerprint, str)
        or not re.fullmatch(r"sha256:[0-9a-fA-F]{64}", fingerprint)
    ):
        raise ValueError("EMBEDDING_RUNTIME_CONTRACT_INVALID")
    signature = {
        "schema_version": _RUNTIME_CONTRACT_SCHEMA,
        "runtime_class": runtime_class,
        "model_id": model_id,
        "dimension": dimension,
    }
    expected_fingerprint = _canonical_hash(signature)
    if not hmac.compare_digest(fingerprint, expected_fingerprint):
        raise ValueError("EMBEDDING_RUNTIME_CONTRACT_FINGERPRINT_INVALID")
    return {**signature, "fingerprint": fingerprint}


def _embedding_runtime_signature(contract: dict[str, Any]) -> tuple[str, str, str, int]:
    return (
        str(contract["schema_version"]),
        str(contract["runtime_class"]),
        str(contract["model_id"]),
        int(contract["dimension"]),
    )


def _query_vectors(value: Any) -> tuple[dict[str, list[float]], dict[str, Any]]:
    payload = _payload(value)
    contract = _embedding_runtime_contract(payload.get("embedding_contract"))
    declared_dimension = contract["dimension"]
    raw = payload.get("vectors") if isinstance(payload, dict) else None
    result: dict[str, list[float]] = {}
    if isinstance(raw, dict):
        pairs = raw.items()
    elif isinstance(raw, list):
        pairs = ((item.get("query_id"), item.get("vector")) for item in raw if isinstance(item, dict))
    else:
        pairs = []
    dimension: int | None = None
    for query_id, vector in pairs:
        if not query_id or not isinstance(vector, list) or not vector or len(vector) > _MAX_EMBEDDING_DIMENSION:
            raise ValueError("VECTOR_PAYLOAD_INVALID")
        if any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in vector):
            raise ValueError("VECTOR_NUMERIC_INVALID")
        values = [float(item) for item in vector]
        if not all(math.isfinite(item) for item in values):
            raise ValueError("VECTOR_NUMERIC_INVALID")
        if dimension is None:
            dimension = len(values)
        if len(values) != dimension or len(values) != declared_dimension:
            raise ValueError("VECTOR_DIMENSION_MISMATCH")
        result[str(query_id)] = values
    return result, contract


def _mongo_base_filter(tenant_id: str, snapshot_id: str, acl: dict[str, Any], asset_types: list[str]) -> dict[str, Any]:
    base = _acl_filter(tenant_id, acl)
    base["snapshot_id"] = snapshot_id
    if asset_types:
        base["asset_type"] = {"$in": asset_types}
    return base


def _search_filter_clauses(tenant_id: str, snapshot_id: str, acl: dict[str, Any], asset_types: list[str]) -> list[dict[str, Any]]:
    clauses: list[dict[str, Any]] = [
        {"equals": {"path": "tenant_id", "value": tenant_id}},
        {"equals": {"path": "snapshot_id", "value": snapshot_id}},
    ]
    if asset_types:
        clauses.append({"in": {"path": "asset_type", "value": asset_types}})
    # Atlas Search must apply authorization before producing candidates.  This
    # compound clause mirrors the post-query fail-closed ACL verification.
    should: list[dict[str, Any]] = [
        {
            "compound": {
                "must": [{"equals": {"path": "acl.visibility", "value": "tenant"}}]
            }
        }
    ]
    groups = [item.lower() for item in _string_list(acl.get("groups"))]
    if groups:
        should.append(
            {
                "compound": {
                    "must": [
                        {"equals": {"path": "acl.visibility", "value": "group"}},
                        {"in": {"path": "acl.groups", "value": groups}},
                    ]
                }
            }
        )
    subject_id = str(acl.get("subject_id") or "")
    if subject_id:
        should.append(
            {
                "compound": {
                    "must": [
                        {"equals": {"path": "acl.visibility", "value": "private"}},
                        {"equals": {"path": "acl.subjects", "value": subject_id}},
                    ]
                }
            }
        )
    clauses.append({"compound": {"should": should, "minimumShouldMatch": 1}})
    return clauses


def _clean_document(document: dict[str, Any], source: str, rank: int, query_ids: list[str]) -> dict[str, Any]:
    technical = document.get("technical_contract") if isinstance(document.get("technical_contract"), dict) else {}
    technical_status = str(document.get("technical_contract_status") or technical.get("status") or "metadata_only")
    if technical_status not in TECHNICAL_STATUSES:
        technical_status = "metadata_only"
    ports = document.get("ports") if isinstance(document.get("ports"), dict) else {
        "inputs": technical.get("inputs") if isinstance(technical.get("inputs"), list) else [],
        "outputs": technical.get("outputs") if isinstance(technical.get("outputs"), list) else [],
    }
    popularity = document.get("popularity") if isinstance(document.get("popularity"), dict) else {}
    return {
        "asset_id": str(document.get("asset_id") or document.get("id") or "")[:200],
        "version": str(document.get("version") or "")[:100],
        "asset_type": str(document.get("asset_type") or document.get("type") or "")[:50],
        "title": str(document.get("title") or "")[:500],
        "description": str(document.get("description") or "")[:2000],
        "category": str(document.get("category") or "")[:200],
        "readme": str(document.get("readme") or document.get("lexical_text_redacted") or "")[:8000],
        "technical_contract_status": technical_status,
        "ports": ports,
        "relations": document.get("relations") if isinstance(document.get("relations"), list) else [],
        "tenant_id": str(document.get("tenant_id") or ""),
        "snapshot_id": str(document.get("snapshot_id") or ""),
        "acl": document.get("acl") if isinstance(document.get("acl"), dict) else {},
        "stars_count": int(document.get("stars_count") or popularity.get("stars") or 0),
        "downloads_count": int(document.get("downloads_count") or popularity.get("downloads") or 0),
        "updated_at": str(document.get("updated_at") or ""),
        "matched_chunk_id": str(document.get("chunk_id") or "")[:200],
        "source": source,
        "source_rank": rank,
        "query_ids": query_ids,
    }


def _enrich_source_results(
    source_results: dict[str, list[dict[str, Any]]],
    parent_documents: list[dict[str, Any]],
    source_limit: int,
) -> tuple[dict[str, list[dict[str, Any]]], int]:
    parents = {
        (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or "")): item
        for item in parent_documents
        if isinstance(item, dict)
    }
    enriched: dict[str, list[dict[str, Any]]] = {}
    missing = 0
    for source, items in source_results.items():
        output: list[dict[str, Any]] = []
        for item in items[:source_limit]:
            if not isinstance(item, dict):
                continue
            identity = (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
            parent = parents.get(identity)
            if parent is None:
                missing += 1
                continue
            merged = dict(parent)
            for key, value in item.items():
                if key.startswith("_") or key in {"score", "chunk_id", "chunk_ordinal", "lexical_text_redacted"}:
                    merged[key] = value
            output.append(merged)
        enriched[source] = output
    return enriched, missing


def _updated_timestamp(document: dict[str, Any]) -> float:
    text = str(document.get("updated_at") or "").strip()
    if not text:
        return 0.0
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
    except (ValueError, OSError):
        return 0.0


def _popularity(document: dict[str, Any], key: str) -> int:
    nested = document.get("popularity") if isinstance(document.get("popularity"), dict) else {}
    try:
        return max(0, int(document.get(f"{key}_count") or nested.get(key) or 0))
    except (TypeError, ValueError):
        return 0


def _find_exact_parents(
    collection: Any,
    base_filter: dict[str, Any],
    exact_keys: list[str],
    exact_terms: list[str],
    source_limit: int,
    query_timeout_ms: int,
) -> list[dict[str, Any]]:
    lanes = (
        {"title_normalized": {"$in": exact_keys}},
        {"aliases_normalized": {"$in": exact_keys}},
        {"asset_id": {"$in": exact_terms}},
    )
    result: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for lane in lanes:
        if not next(iter(lane.values()))["$in"]:
            continue
        cursor = collection.find({"$and": [base_filter, lane]}, {"_id": 0}, max_time_ms=query_timeout_ms)
        cursor = cursor.sort([("asset_id", 1), ("version", 1)]).limit(source_limit)
        for document in cursor:
            identity = (str(document.get("asset_id") or document.get("id") or ""), str(document.get("version") or ""))
            if all(identity) and identity not in seen:
                seen.add(identity)
                result.append(document)
            if len(result) >= source_limit:
                return result
    return result


def _retrieve_from_mongodb(
    *,
    mongodb_uri: str,
    database_name: str,
    chunks_collection: str,
    pointer_collection: str,
    assets_collection: str = "catalog_assets",
    tenant_id: str,
    snapshot_id: str,
    acl: dict[str, Any],
    query_plan: dict[str, Any],
    vectors: dict[str, list[float]],
    query_embedding_contract: dict[str, Any],
    provider_mode: str,
    lexical_index_name: str,
    vector_index_name: str,
    source_limit: int,
    server_selection_timeout_ms: int,
    query_timeout_ms: int,
) -> dict[str, Any]:
    client = MongoClient(
        mongodb_uri,
        serverSelectionTimeoutMS=server_selection_timeout_ms,
        connectTimeoutMS=server_selection_timeout_ms,
        socketTimeoutMS=query_timeout_ms,
        appname="business-work-design-agent-retriever",
    )
    try:
        database = client[database_name]
        pointer = database[pointer_collection].find_one(
            {"tenant_id": tenant_id},
            {"_id": 0, "snapshot_id": 1, "active_snapshot_id": 1, "embedding_contract": 1},
            max_time_ms=query_timeout_ms,
        )
        active_snapshot_id = str((pointer or {}).get("snapshot_id") or (pointer or {}).get("active_snapshot_id") or "")
        if not active_snapshot_id:
            return {"active_snapshot_id": "", "source_results": {}}
        if active_snapshot_id != snapshot_id:
            return {"active_snapshot_id": active_snapshot_id, "source_results": {}}
        try:
            active_contract = _embedding_runtime_contract((pointer or {}).get("embedding_contract"))
        except ValueError:
            return {"active_snapshot_id": active_snapshot_id, "contract_error": "CATALOG_EMBEDDING_CONTRACT_MISSING", "source_results": {}}
        if (
            _embedding_runtime_signature(active_contract) != _embedding_runtime_signature(query_embedding_contract)
            or not hmac.compare_digest(
                str(active_contract["fingerprint"]), str(query_embedding_contract["fingerprint"])
            )
        ):
            return {"active_snapshot_id": active_snapshot_id, "contract_error": "QUERY_EMBEDDING_CONTRACT_MISMATCH", "source_results": {}}

        collection = database[chunks_collection]
        parents_collection = database[assets_collection]
        queries = [item for item in query_plan.get("queries", []) if isinstance(item, dict)]
        search_text = " ".join(str(item.get("text") or "") for item in queries if item.get("kind") != "exact")[:4000]
        exact_terms = [str(item.get("text") or "")[:500] for item in queries if item.get("kind") == "exact"]
        exact_keys = [key for key in (_normalize_exact_key(term) for term in exact_terms) if key]
        asset_types = sorted(
            {
                str(asset_type)
                for item in queries
                for asset_type in item.get("expected_asset_types", [])
                if asset_type in {"component", "flow"}
            }
        )
        query_ids = [str(item.get("query_id")) for item in queries if item.get("query_id")]
        base_filter = _mongo_base_filter(tenant_id, snapshot_id, acl, asset_types)
        search_filters = _search_filter_clauses(tenant_id, snapshot_id, acl, asset_types)
        exact_docs: list[dict[str, Any]] = []
        if exact_keys or exact_terms:
            exact_docs = _find_exact_parents(
                parents_collection,
                base_filter,
                exact_keys,
                exact_terms,
                source_limit,
                query_timeout_ms,
            )

        if provider_mode == "application_rrf":
            lexical_docs = list(
                collection.aggregate(
                    [
                        {
                            "$search": {
                                "index": lexical_index_name,
                                "compound": {
                                    "must": [{"text": {"query": search_text, "path": ["title", "description", "lexical_text_redacted", "category"]}}],
                                    "filter": search_filters,
                                },
                            }
                        },
                        {"$limit": source_limit},
                        {"$project": {"_id": 0, "score": {"$meta": "searchScore"}, "asset_id": 1, "version": 1, "asset_type": 1, "title": 1, "description": 1, "category": 1, "readme": 1, "lexical_text_redacted": 1, "technical_contract_status": 1, "ports": 1, "relations": 1, "tenant_id": 1, "snapshot_id": 1, "acl": 1, "stars_count": 1, "downloads_count": 1, "updated_at": 1, "chunk_id": 1}},
                    ],
                    maxTimeMS=query_timeout_ms,
                )
            )
            source_results = {"exact": exact_docs, "lexical": lexical_docs}
            for query_id in query_ids:
                vector_docs = list(
                    collection.aggregate(
                        [
                            {
                                "$vectorSearch": {
                                    "index": vector_index_name,
                                    "path": "embedding.vector",
                                    "queryVector": vectors[query_id],
                                    "numCandidates": min(1000, source_limit * 10),
                                    "limit": source_limit,
                                    "filter": base_filter,
                                }
                            },
                            {"$project": {"_id": 0, "score": {"$meta": "vectorSearchScore"}, "asset_id": 1, "version": 1, "asset_type": 1, "title": 1, "description": 1, "category": 1, "readme": 1, "lexical_text_redacted": 1, "technical_contract_status": 1, "ports": 1, "relations": 1, "tenant_id": 1, "snapshot_id": 1, "acl": 1, "stars_count": 1, "downloads_count": 1, "updated_at": 1, "chunk_id": 1}},
                        ],
                        maxTimeMS=query_timeout_ms,
                    )
                )
                source_results[f"vector:{query_id}"] = vector_docs
        else:
            fusion_operator = "$rankFusion" if provider_mode == "native_rank_fusion" else "$scoreFusion"
            fusion_pipelines: dict[str, list[dict[str, Any]]] = {
                "lexical": [
                    {
                        "$search": {
                            "index": lexical_index_name,
                            "compound": {
                                "must": [{"text": {"query": search_text, "path": ["title", "description", "lexical_text_redacted", "category"]}}],
                                "filter": search_filters,
                            },
                        }
                    },
                    {"$limit": source_limit},
                ]
            }
            native_pipeline_query_ids: dict[str, str] = {}
            native_weights: dict[str, float] = {"lexical": 1.0}
            query_kind_by_id = {
                str(item.get("query_id")): str(item.get("kind") or "")
                for item in queries
                if item.get("query_id")
            }
            for index, query_id in enumerate(query_ids):
                pipeline_name = f"vector_{index:02d}"
                native_pipeline_query_ids[pipeline_name] = query_id
                native_weights[pipeline_name] = QUERY_KIND_WEIGHTS.get(query_kind_by_id.get(query_id, ""), 1.0)
                fusion_pipelines[pipeline_name] = [
                    {
                        "$vectorSearch": {
                            "index": vector_index_name,
                            "path": "embedding.vector",
                            "queryVector": vectors[query_id],
                            "numCandidates": min(1000, source_limit * 10),
                            "limit": source_limit,
                            "filter": base_filter,
                        }
                    }
                ]
            fusion_spec: dict[str, Any] = {
                "input": {"pipelines": fusion_pipelines},
                "combination": {"weights": native_weights},
                "scoreDetails": True,
            }
            if provider_mode == "native_score_fusion":
                fusion_spec["input"]["normalization"] = "none"
                fusion_spec["combination"]["method"] = "avg"
            score_details_meta = "searchScoreDetails" if provider_mode == "native_rank_fusion" else "scoreDetails"
            fused_docs = list(
                collection.aggregate(
                    [
                        {fusion_operator: fusion_spec},
                        {"$addFields": {"_fusion_score_details": {"$meta": score_details_meta}}},
                        {"$limit": source_limit},
                    ],
                    maxTimeMS=query_timeout_ms,
                )
            )
            source_results = {"exact": exact_docs, "native_fused": fused_docs}

        # Search chunks only establish candidate identity and ranking evidence.
        # Re-fetch authoritative parent metadata under the same tenant/snapshot/
        # ACL filter so ports, relations, README, and popularity cannot be lost
        # or forged by a stale/orphan chunk.
        identities = sorted(
            {
                (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
                for items in source_results.values()
                for item in items[:source_limit]
                if isinstance(item, dict)
                and str(item.get("asset_id") or item.get("id") or "")
                and str(item.get("version") or "")
            }
        )
        parent_documents: list[dict[str, Any]] = []
        if identities:
            for offset in range(0, len(identities), 250):
                batch = identities[offset : offset + 250]
                identity_filter = {"$or": [{"asset_id": asset_id, "version": version} for asset_id, version in batch]}
                parent_documents.extend(
                    list(
                        parents_collection.find(
                            {"$and": [base_filter, identity_filter]},
                            {"_id": 0},
                            max_time_ms=query_timeout_ms,
                        )
                    )
                )
        source_results, missing_parent_count = _enrich_source_results(source_results, parent_documents, source_limit)

        # Relation payloads are never trusted as documents. Only parent relation
        # IDs are re-queried from the authoritative asset collection.
        relation_refs: list[tuple[str, str]] = []
        for source_items in source_results.values():
            for document in source_items[:source_limit]:
                for relation in document.get("relations", []) if isinstance(document.get("relations"), list) else []:
                    if not isinstance(relation, dict):
                        continue
                    ref = (str(relation.get("asset_id") or ""), str(relation.get("version") or ""))
                    if all(ref) and ref not in relation_refs:
                        relation_refs.append(ref)
                    if len(relation_refs) >= source_limit:
                        break
        if relation_refs:
            relation_identity = {
                "$or": [{"asset_id": asset_id, "version": version} for asset_id, version in relation_refs]
            }
            source_results["relation"] = list(
                parents_collection.find(
                    {"$and": [base_filter, relation_identity]},
                    {"_id": 0},
                    limit=source_limit,
                    max_time_ms=query_timeout_ms,
                )
            )
        return {
            "active_snapshot_id": active_snapshot_id,
            "source_results": source_results,
            "native_pipeline_query_ids": native_pipeline_query_ids if provider_mode != "application_rrf" else {},
            "missing_parent_count": missing_parent_count,
        }
    finally:
        client.close()


def _rrf(
    source_results: dict[str, list[dict[str, Any]]],
    k: int = 60,
    source_weights: dict[str, float] | None = None,
) -> list[dict[str, Any]]:
    scores: dict[tuple[str, str], float] = {}
    documents: dict[tuple[str, str], dict[str, Any]] = {}
    ranks: dict[tuple[str, str], dict[str, int]] = {}
    for source, items in source_results.items():
        seen_in_source: set[tuple[str, str]] = set()
        for rank, item in enumerate(items[:MAX_SOURCE_CANDIDATES], start=1):
            if not isinstance(item, dict):
                continue
            key = (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
            if not all(key) or key in seen_in_source:
                continue
            seen_in_source.add(key)
            default_weight = 2.0 if source == "exact" else 0.25 if source == "relation" else 1.0
            weight = float((source_weights or {}).get(source, default_weight))
            scores[key] = scores.get(key, 0.0) + weight / (k + rank)
            ranks.setdefault(key, {})[source] = rank
            if key not in documents:
                documents[key] = dict(item)
            elif source == "native_fused" and isinstance(item.get("_fusion_score_details"), dict):
                # exact results are inserted first, but native score details are
                # the authoritative evidence for per-query contribution trace.
                documents[key]["_fusion_score_details"] = dict(item["_fusion_score_details"])
    ordered = sorted(
        scores,
        key=lambda key: (
            -scores[key],
            -_popularity(documents[key], "stars"),
            -_popularity(documents[key], "downloads"),
            -_updated_timestamp(documents[key]),
            key[0],
            key[1],
        ),
    )
    result: list[dict[str, Any]] = []
    for fused_rank, key in enumerate(ordered, start=1):
        item = dict(documents[key])
        item["_fused_score"] = scores[key]
        item["_source_ranks"] = ranks[key]
        item["_fused_rank"] = fused_rank
        result.append(item)
    return result


def _native_vector_contributions(
    document: dict[str, Any], pipeline_query_ids: dict[str, str]
) -> tuple[list[str], dict[str, int | float | str]]:
    score_details = document.get("_fusion_score_details")
    details = score_details.get("details") if isinstance(score_details, dict) else None
    if not isinstance(details, list):
        return [], {}
    matched: list[str] = []
    ranks: dict[str, int | float | str] = {}
    for detail in details:
        if not isinstance(detail, dict):
            continue
        query_id = pipeline_query_ids.get(str(detail.get("inputPipelineName") or ""))
        if not query_id:
            continue
        if query_id not in matched:
            matched.append(query_id)
        rank_or_score = detail.get("rank")
        if rank_or_score in (None, "N/A"):
            rank_or_score = detail.get("inputPipelineRawScore", detail.get("value"))
        if rank_or_score is not None:
            ranks[query_id] = rank_or_score
    return sorted(matched), ranks


def retrieve_catalog_candidates(
    query_plan: Any,
    query_vectors: Any,
    *,
    tenant_id: str = "",
    catalog_snapshot_id: str = "",
    acl_context: Any = None,
    provider_mode: str,
    mongodb_uri: Any,
    database_name: str = "business_work_design",
    chunks_collection: str = "catalog_asset_chunks",
    assets_collection: str = "catalog_assets",
    pointer_collection: str = "catalog_active_pointers",
    lexical_index_name: str = "catalog_lexical",
    vector_index_name: str = "catalog_vector",
    top_n: int = 20,
    source_limit: int = 50,
    server_selection_timeout_ms: int = 5000,
    query_timeout_ms: int = 10000,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    plan = _payload(query_plan)
    mode = str(provider_mode or "").strip()
    if mode not in PROVIDER_MODES:
        return _error(trace_id, "UNSUPPORTED_PROVIDER_MODE", "지원되지 않는 provider_mode입니다.")
    if not plan.get("ok"):
        return _error(trace_id, "INVALID_QUERY_PLAN", "성공한 query plan이 필요합니다.")
    tenant = str(plan.get("tenant_id") or "").strip()
    snapshot = str(plan.get("catalog_snapshot_id") or "").strip()
    supplied_tenant = str(tenant_id or "").strip()
    supplied_snapshot = str(catalog_snapshot_id or "").strip()
    if not tenant or not snapshot:
        return _error(trace_id, "CATALOG_SCOPE_MISSING", "query plan에 tenant_id와 catalog_snapshot_id가 필요합니다.")
    if (supplied_tenant and supplied_tenant != tenant) or (supplied_snapshot and supplied_snapshot != snapshot):
        return _error(trace_id, "QUERY_PLAN_SCOPE_MISMATCH", "query plan의 tenant 또는 snapshot 계약이 일치하지 않습니다.")
    plan_acl = plan.get("acl") if isinstance(plan.get("acl"), dict) else {}
    acl = _payload(acl_context) if acl_context is not None else plan_acl
    if not plan_acl.get("subject_id"):
        return _error(trace_id, "ACL_CONTEXT_MISSING", "query plan에 검증 가능한 ACL context가 필요합니다.")
    if str(plan_acl.get("subject_id") or "") != str(acl.get("subject_id") or "") or {
        item.lower() for item in _string_list(plan_acl.get("groups"))
    } != {item.lower() for item in _string_list(acl.get("groups"))}:
        return _error(trace_id, "ACL_CONTEXT_MISMATCH", "query plan을 만든 ACL context와 현재 ACL context가 다릅니다.")
    lock_fields = ("work_definition_id", "work_definition_revision", "approved_hash", "design_scope_sha256")
    if any(plan.get(field) in (None, "") for field in lock_fields) or not str(plan.get("approved_hash")).startswith("sha256:"):
        return _error(trace_id, "QUERY_PLAN_LOCK_MISSING", "query plan에 승인 업무와 design scope lock이 필요합니다.")
    query_plan_hash = str(plan.get("query_plan_sha256") or "")
    plan_core = {
        key: value
        for key, value in plan.items()
        if key not in {"ok", "status", "query_plan_sha256", "trace_id"}
    }
    if (
        not re.fullmatch(r"sha256:[0-9a-fA-F]{64}", query_plan_hash)
        or not hmac.compare_digest(query_plan_hash.lower(), _canonical_hash(plan_core).lower())
    ):
        return _error(trace_id, "QUERY_PLAN_HASH_MISMATCH", "query plan hash가 canonical payload와 일치하지 않습니다.")
    if not isinstance(plan.get("queries"), list) or not plan["queries"]:
        return _error(trace_id, "INVALID_QUERY_PLAN", "검색 query가 없습니다.")
    provider_query_limit = MAX_NATIVE_QUERY_COUNT if mode.startswith("native_") else MAX_QUERY_COUNT
    if len(plan["queries"]) > provider_query_limit:
        return _error(
            trace_id,
            "SEARCH_QUERY_LIMIT_EXCEEDED",
            "선택한 검색 provider가 한 번에 처리할 수 있는 query 수를 초과했습니다.",
            details={"provider_mode": mode, "query_count": len(plan["queries"]), "maximum": provider_query_limit},
        )
    uri = _secret(mongodb_uri)
    if not uri:
        return _error(trace_id, "CATALOG_CONFIGURATION_MISSING", "MongoDB 연결 설정이 필요합니다.")
    vector_payload = _payload(query_vectors)
    if any(str(vector_payload.get(field) or "") != str(plan.get(field) or "") for field in ("design_scope_sha256", "query_plan_sha256")):
        return _error(trace_id, "QUERY_VECTOR_PLAN_MISMATCH", "query vectors가 현재 query plan의 scope/hash lock과 일치하지 않습니다.")
    try:
        vectors, query_embedding_contract = _query_vectors(query_vectors)
    except ValueError as exc:
        code = str(exc)
        messages = {
            "EMBEDDING_RUNTIME_CONTRACT_INVALID": "query vector의 embedding runtime 계약이 유효하지 않습니다.",
            "EMBEDDING_RUNTIME_CONTRACT_FINGERPRINT_INVALID": "query vector의 embedding runtime fingerprint가 계약과 일치하지 않습니다.",
            "VECTOR_PAYLOAD_INVALID": "query vector payload가 유효하지 않습니다.",
            "VECTOR_NUMERIC_INVALID": "query vector는 bool이 아닌 유한 숫자로만 구성되어야 합니다.",
            "VECTOR_DIMENSION_MISMATCH": "query vector dimension이 계약 또는 다른 vector와 다릅니다.",
        }
        return _error(trace_id, code if code in messages else "VECTOR_PAYLOAD_INVALID", messages.get(code, "query vector가 유효하지 않습니다."))
    query_ids = {str(item.get("query_id")) for item in plan["queries"] if isinstance(item, dict) and item.get("query_id")}
    if len(query_ids) != len(plan["queries"]):
        return _error(trace_id, "INVALID_QUERY_PLAN", "모든 query에는 중복되지 않는 query_id가 필요합니다.")
    if not query_ids or set(vectors) != query_ids:
        return _error(trace_id, "VECTOR_QUERY_MISSING", "모든 query plan ID에 정확히 대응하는 vector가 필요합니다.")
    top_n = max(1, min(50, int(top_n or 20)))
    source_limit = max(top_n, min(MAX_SOURCE_CANDIDATES, int(source_limit or 50)))
    try:
        safe_database_name = _safe_identifier(database_name, "business_work_design")
        safe_chunks_collection = _safe_identifier(chunks_collection, "catalog_asset_chunks")
        safe_assets_collection = _safe_identifier(assets_collection, "catalog_assets")
        safe_pointer_collection = _safe_identifier(pointer_collection, "catalog_active_pointers")
        safe_lexical_index_name = _safe_identifier(lexical_index_name, "catalog_lexical")
        safe_vector_index_name = _safe_identifier(vector_index_name, "catalog_vector")
    except ValueError:
        return _error(trace_id, "INVALID_SEARCH_CONFIGURATION", "database, collection 또는 index 이름 형식이 잘못되었습니다.")
    try:
        backend_result = _retrieve_from_mongodb(
            mongodb_uri=uri,
            database_name=safe_database_name,
            chunks_collection=safe_chunks_collection,
            assets_collection=safe_assets_collection,
            pointer_collection=safe_pointer_collection,
            tenant_id=tenant,
            snapshot_id=snapshot,
            acl=acl,
            query_plan=plan,
            vectors=vectors,
            query_embedding_contract=query_embedding_contract,
            provider_mode=mode,
            lexical_index_name=safe_lexical_index_name,
            vector_index_name=safe_vector_index_name,
            source_limit=source_limit,
            server_selection_timeout_ms=max(1000, min(30000, int(server_selection_timeout_ms or 5000))),
            query_timeout_ms=max(1000, min(60000, int(query_timeout_ms or 10000))),
        )
    except OperationFailure as exc:
        if exc.code == 50:
            return _error(trace_id, "SEARCH_TIMEOUT", "MongoDB 검색 실행 시간이 초과되었습니다.", retryable=True, details={"mongo_code": exc.code})
        return _error(trace_id, "SEARCH_OPERATOR_UNAVAILABLE", "선택한 검색 provider mode를 MongoDB가 실행하지 못했습니다.", retryable=False, details={"provider_mode": mode, "mongo_code": exc.code})
    except (ServerSelectionTimeoutError, ConnectionFailure) as exc:
        return _error(trace_id, "SEARCH_TIMEOUT", "MongoDB 검색 연결 시간이 초과되었습니다.", retryable=True, details={"exception_type": type(exc).__name__})
    except (ConfigurationError, PyMongoError) as exc:
        return _error(trace_id, "SEARCH_PROVIDER_ERROR", "MongoDB 검색 provider 오류가 발생했습니다.", retryable=False, details={"exception_type": type(exc).__name__})

    active_snapshot = str(backend_result.get("active_snapshot_id") or "")
    if not active_snapshot:
        return _error(trace_id, "CATALOG_NOT_READY", "활성 catalog snapshot이 없습니다.")
    if active_snapshot != snapshot:
        return _error(trace_id, "ACTIVE_SNAPSHOT_MISMATCH", "요청 snapshot이 현재 활성 snapshot과 일치하지 않습니다.", details={"requested_snapshot_id": snapshot})
    contract_error = str(backend_result.get("contract_error") or "")
    if contract_error:
        messages = {
            "CATALOG_EMBEDDING_CONTRACT_MISSING": "활성 catalog pointer에 embedding 계약이 없습니다. snapshot을 재검증·재활성화해야 합니다.",
            "QUERY_EMBEDDING_CONTRACT_MISMATCH": "query embedding runtime 계약이 활성 catalog와 일치하지 않습니다.",
        }
        return _error(trace_id, contract_error, messages.get(contract_error, "embedding 계약이 일치하지 않습니다."))
    source_results = backend_result.get("source_results") if isinstance(backend_result.get("source_results"), dict) else {}
    query_kind_by_id = {
        str(item.get("query_id")): str(item.get("kind") or "")
        for item in plan["queries"]
        if isinstance(item, dict) and item.get("query_id")
    }
    source_weights = {
        f"vector:{query_id}": QUERY_KIND_WEIGHTS.get(kind, 1.0)
        for query_id, kind in query_kind_by_id.items()
    }

    def completed_result(
        selected_candidates: list[dict[str, Any]],
        rejected_counts: dict[str, int],
        *,
        empty_result_reason: str | None = None,
    ) -> dict[str, Any]:
        """Return a sealed retrieval result, including a valid empty result.

        An empty *authorized* result is not a backend failure.  Downstream
        blueprint generation can safely continue as long as it receives an
        explicit empty allowlist: it must then avoid all catalog references.
        Connection, snapshot, embedding-contract, and query validation errors
        are handled before this point and remain fail-closed.
        """
        retrieval_trace: dict[str, Any] = {
            "tenant_id": tenant,
            "snapshot_id": snapshot,
            "work_definition_id": str(plan["work_definition_id"]),
            "work_definition_revision": plan["work_definition_revision"],
            "approved_hash": str(plan["approved_hash"]),
            "design_scope_sha256": str(plan["design_scope_sha256"]),
            "query_plan_sha256": str(plan.get("query_plan_sha256") or ""),
            "source_counts": {key: len(value) for key, value in source_results.items() if isinstance(value, list)},
            "post_filter_rejected": rejected_counts,
            "returned_count": len(selected_candidates),
            "rrf_k": 60,
            "query_kind_weights": {
                query_id: QUERY_KIND_WEIGHTS.get(kind, 1.0)
                for query_id, kind in sorted(query_kind_by_id.items())
            },
            "silent_fallback_used": False,
            "missing_parent_count": int(backend_result.get("missing_parent_count") or 0),
        }
        if empty_result_reason:
            retrieval_trace["empty_result_reason"] = empty_result_reason
        return {
            "ok": True,
            "status": "COMPLETED",
            "tenant_id": tenant,
            "snapshot_id": snapshot,
            "work_definition_id": str(plan["work_definition_id"]),
            "work_definition_revision": plan["work_definition_revision"],
            "approved_hash": str(plan["approved_hash"]),
            "design_scope_sha256": str(plan["design_scope_sha256"]),
            "query_plan_sha256": str(plan.get("query_plan_sha256") or ""),
            "provider_mode": mode,
            "candidates": selected_candidates,
            "retrieval_trace": retrieval_trace,
            "trace_id": trace_id,
        }

    fused = _rrf(
        {key: value for key, value in source_results.items() if isinstance(value, list)},
        source_weights=source_weights,
    )
    if not fused:
        return completed_result(
            [],
            {"scope_or_acl": 0, "invalid_identity": 0},
            empty_result_reason="NO_CANDIDATES",
        )

    candidates: list[dict[str, Any]] = []
    rejected_counts = {"scope_or_acl": 0, "invalid_identity": 0}
    native_pipeline_query_ids = (
        backend_result.get("native_pipeline_query_ids")
        if isinstance(backend_result.get("native_pipeline_query_ids"), dict)
        else {}
    )
    for item in fused:
        if not _acl_allows(item, tenant, snapshot, acl):
            rejected_counts["scope_or_acl"] += 1
            continue
        ranks = item.get("_source_ranks") if isinstance(item.get("_source_ranks"), dict) else {}
        vector_ranks = {
            source.split(":", 1)[1]: rank
            for source, rank in ranks.items()
            if source.startswith("vector:")
        }
        matched_query_ids = sorted(vector_ranks)
        native_query_ids, native_vector_evidence = _native_vector_contributions(item, native_pipeline_query_ids)
        if native_query_ids:
            matched_query_ids = native_query_ids
        combined_match_sources = [
            source
            for source in ("exact", "lexical", "native_fused", "relation")
            if ranks.get(source) is not None
        ]
        cleaned = _clean_document(item, "fusion", int(item.get("_fused_rank") or 0), matched_query_ids)
        if not cleaned["asset_id"] or not cleaned["version"] or cleaned["asset_type"] not in {"component", "flow"}:
            rejected_counts["invalid_identity"] += 1
            continue
        cleaned["recommendation_status"] = "candidate"
        cleaned["retrieval_trace"] = {
            "exact_rank": ranks.get("exact"),
            "lexical_rank": ranks.get("lexical"),
            "vector_rank": ranks.get("vector") or (min(vector_ranks.values()) if vector_ranks else None),
            "vector_ranks_by_query_id": vector_ranks,
            "native_vector_evidence_by_query_id": native_vector_evidence,
            "native_fused_rank": ranks.get("native_fused"),
            "relation_rank": ranks.get("relation"),
            "combined_match_sources": combined_match_sources,
            "fused_rank": int(item.get("_fused_rank") or 0),
            "fused_score": round(float(item.get("_fused_score") or 0.0), 12),
            "snapshot_id": snapshot,
            "query_ids": matched_query_ids,
        }
        candidates.append(cleaned)
        if len(candidates) >= top_n:
            break
    if not candidates:
        return completed_result(
            [],
            rejected_counts,
            empty_result_reason="NO_AUTHORIZED_CANDIDATES",
        )
    return completed_result(candidates, rejected_counts)


def _error(
    trace_id: str,
    code: str,
    message: str,
    *,
    retryable: bool = False,
    details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
    }


class CatalogHybridRetrieverComponent(Component):
    display_name = "21 Catalog Hybrid Retriever"
    description = "활성 snapshot에서 tenant/ACL을 적용한 exact, lexical, vector 후보를 결합합니다. 정상 검색 결과가 없으면 빈 allowlist용 완료 결과를 반환해 catalog 재사용 없이 설계를 계속합니다."
    icon = "SearchCheck"
    name = "CatalogHybridRetriever"

    inputs = [
        DataInput(name="query_plan", display_name="Search Query Plan", required=True),
        DataInput(name="query_vectors", display_name="Query Vectors", required=True),
        DropdownInput(name="provider_mode", display_name="Provider Mode", options=sorted(PROVIDER_MODES), value="application_rrf"),
        SecretStrInput(name="mongodb_uri", display_name="MongoDB URI", required=True),
        MessageTextInput(name="database_name", display_name="MongoDB Database", value="business_work_design", advanced=True),
        MessageTextInput(name="chunks_collection", display_name="Chunks Collection", value="catalog_asset_chunks", advanced=True),
        MessageTextInput(name="assets_collection", display_name="Assets Collection", value="catalog_assets", advanced=True),
        MessageTextInput(name="pointer_collection", display_name="Active Pointer Collection", value="catalog_active_pointers", advanced=True),
        MessageTextInput(name="lexical_index_name", display_name="Lexical Index", value="catalog_lexical", advanced=True),
        MessageTextInput(name="vector_index_name", display_name="Vector Index", value="catalog_vector", advanced=True),
        IntInput(name="top_n", display_name="Final Top N", value=20, advanced=True),
        IntInput(name="source_limit", display_name="Per-source Candidate Limit", value=50, advanced=True),
        IntInput(name="server_selection_timeout_ms", display_name="Server Selection Timeout (ms)", value=5000, advanced=True),
        IntInput(name="query_timeout_ms", display_name="Query Timeout (ms)", value=10000, advanced=True),
    ]
    outputs = [Output(name="retrieval_result", display_name="Retrieval Result", method="build_retrieval_result", types=["Data"])]

    def build_retrieval_result(self) -> Data:
        result = retrieve_catalog_candidates(
            self.query_plan,
            self.query_vectors,
            provider_mode=self.provider_mode,
            mongodb_uri=self.mongodb_uri,
            database_name=getattr(self, "database_name", "business_work_design"),
            chunks_collection=getattr(self, "chunks_collection", "catalog_asset_chunks"),
            assets_collection=getattr(self, "assets_collection", "catalog_assets"),
            pointer_collection=getattr(self, "pointer_collection", "catalog_active_pointers"),
            lexical_index_name=getattr(self, "lexical_index_name", "catalog_lexical"),
            vector_index_name=getattr(self, "vector_index_name", "catalog_vector"),
            top_n=getattr(self, "top_n", 20),
            source_limit=getattr(self, "source_limit", 50),
            server_selection_timeout_ms=getattr(self, "server_selection_timeout_ms", 5000),
            query_timeout_ms=getattr(self, "query_timeout_ms", 10000),
        )
        self.status = f"Hybrid retrieval: {result.get('status')} / mode={result.get('provider_mode', self.provider_mode)} / candidates={len(result.get('candidates', []))}"
        return Data(data=result)
